#!/usr/bin/env python3
"""Generate test_s68dev_read.py (the reader's end-to-end check on SYNTHETIC rows) from s66b's test_s66b_read.py (53e1efec, ALL PASS on the
s66b reader) by asserted edits.  The test now takes the fixture arm as its second argument (b or a) and is run once per arm, so each arm's
seed block, exploiter name, exploiter env (its DEV start line) and play worlds (a: 96 on the exploiter side) are exercised; the lane-read
fixtures (T1 lane, T4) write BOTH arms, each with its own seed block, name and exploiter worlds, since analyze_lane reads every arm.
Changed: the docstring head; ARM from argv; PW per arm; the DEV start text per arm (START_OF); 's66b' lane strings -> 's68dev'; the bar
cases at +0.030 (s66b's +0.015 cases moved to the new mean floor; +0.010 -> +0.025); the canonical-line and status texts; the './<arm>/'
paths; a helper arm_rows() for the per-arm lane fixtures.  The 'sc8' ROW KEY (the adapter's probe entries) is unchanged.
Usage: python3 make_s68dev_tests.py   (refuses to overwrite)"""
import hashlib
from pathlib import Path

H = Path(__file__).resolve().parent
sha = lambda b: hashlib.sha256(b).hexdigest()
src = (H / "src_test_s66b_read.py").read_text()
assert sha(src.encode()) == "53e1efec5ace87f39258dcfc1c43edba3d2d69942a3fefda98935c9a1764096b", sha(src.encode())
s = src
n = 0


def sub(old, new, count=1):
    global s, n
    assert s.count(old) == count, (s.count(old), old[:140])
    s = s.replace(old, new)
    n += 1


sub('''"""s66b reader end-to-end check on SYNTHETIC rows (no deal is played).''',
    '''"""s68dev reader end-to-end check on SYNTHETIC rows (no deal is played), run once per fixture arm (b, a): generated by make_s68dev_tests.py from
s66b's test (the description below is s66b's; the bar cases are at s68dev's +0.030; the lane fixtures write both arms).
s66b's description:''')
sub("  usage: cd /private/tmp && nice -n 15 python3 test_s66b_read.py <s66b_read.py>", "  usage: cd /private/tmp && nice -n 15 python3 test_s68dev_read.py <s68dev_read.py> <arm: b | a>")
sub("spec = importlib.util.spec_from_file_location('s66b_read', READER);", "spec = importlib.util.spec_from_file_location('s68dev_read', READER);")
sub("ARM = 'sc8'   # the fixture's (only) arm: R48 + the singleton challenger vs R48, 64 play worlds on both sides; the battery reads this arm",
    "ARM = sys.argv[2] if len(sys.argv) > 2 else 'b'   # the fixture arm (b: 64 / 64 play worlds; a: 96 exploiter / 64 defender); the battery reads arm b\nassert ARM in rd.ARM_ORDER, ARM")
sub("PW = dict(rd.PLAY_WORLDS)   # the play worlds each side's search records report (64 / 64)", "PW = dict(rd.PLAY_WORLDS[ARM])   # the play worlds each side's search records report in this arm")
sub("START = '(S66_EXPLOITER=sc8: the singleton challenger, PR #1153 at eb0975da; served budgets and widths on both sides)'   # the launcher's DEV start text after the exploiter name",
    "START_OF = lambda arm: f\"(exploiter env: {rd.ARM_SPEC[arm]['env']}; defender at served budgets and widths)\"   # the launcher's DEV start text after the exploiter name\nSTART = START_OF(ARM)")
sub("    lines = [f'{TS0} s66b armed (pid 4242,", "    lines = [f'{TS0} s68dev armed (pid 4242,")
sub("waiting for the RELEASE token /root/claude_s66b.RELEASE,", "waiting for the RELEASE token /root/claude_s68dev.RELEASE,")
sub('''             f"{TS0} s66b: adopting the paused S17''', '''             f"{TS0} s68dev: adopting the paused S17''')
sub("        lines.append(f'{TS0} s66b DEV start {arm}: defender {rd.DEF_NAME} (R48 as served) vs exploiter {c} {start}; deals",
    "        lines.append(f'{TS0} s68dev DEV start {arm}: defender {rd.DEF_NAME} (R48 as served) vs exploiter {c} {start if arm == ARM else START_OF(arm)}; deals")
sub("            lines.append(f'{TS0} s66b DEV END {arm} rc=", "            lines.append(f'{TS0} s68dev DEV END {arm} rc=")
sub("        lines.append(f'{TS0} ABORT: s66b run group", "        lines.append(f'{TS0} ABORT: s68dev run group")
sub('''            lines.append(f"{TS0} s66b: S17 left PAUSED by s66b (request token '{tok}', still this lane's; terminal: {TS0} {rd.TERMINAL}; handoff /root/claude-s17-handoff.s66b);''',
    '''            lines.append(f"{TS0} s68dev: S17 left PAUSED by s68dev (request token '{tok}', still this lane's; terminal: {TS0} {rd.TERMINAL}; handoff /root/claude-s17-handoff.s68dev);''')
sub("prefix='s66b-e2e-'", "prefix='s68dev-e2e-'")
sub('''check('T1 canonical lines carry the arm, the candidate, the numbers and the verdict', any(f'{m:+.4f}' in l and "[sc8] R48 + the singleton challenger (PR #1153 at eb0975da, '-sc8'; no knob changed) vs R48 as served" in l for l in cl) and any('Verdict DEV_PASS' in l and 'inside the 3 s budget' in l for l in cl), cl[:1])''',
    '''check('T1 canonical lines carry the arm, the candidate, the numbers and the verdict', any(f'{m:+.4f}' in l and f"s68dev [{ARM}] R48 + sc8 + bwc" in l and "vs R48 as served" in l for l in cl) and any('Verdict DEV_PASS' in l and 'inside 3 s' in l for l in cl), cl[:1])''')
sub('''with tempfile.TemporaryDirectory(prefix='s66b-lane-', dir='/private/tmp') as tmp:
    sums = []
    for arm in rd.ARM_ORDER:
        a = rd.ARM_SPEC[arm]
        rs_ = [dict(copy.deepcopy(r), seed=r['seed'] - SEED0 + a['seed0'], exploiter_base=a['cand']) for r in base]
''', '''def arm_rows(rs, arm):
    """the fixture rows moved to another arm: its seed block, exploiter name and exploiter play worlds (search records)"""
    a = rd.ARM_SPEC[arm]
    out = [dict(copy.deepcopy(r), seed=r['seed'] - SEED0 + a['seed0'], exploiter_base=a['cand']) for r in rs]
    for r in out:
        for h in r['dhist']['ex']:
            if h[0] == '-decision-v1':
                h[18] = rd.PLAY_WORLDS[arm]['ex']
    return out
with tempfile.TemporaryDirectory(prefix='s68dev-lane-', dir='/private/tmp') as tmp:
    sums = []
    for arm in rd.ARM_ORDER:
        rs_ = arm_rows(base, arm)
''')
sub("    def host_layout(tmp, *, sha=FAKE_SHA, res_sha=None, res_lane='s66b', status=None):", "    def host_layout(tmp, *, sha=FAKE_SHA, res_sha=None, res_lane='s68dev', status=None):")
sub("        st = Path(tmp) / 'claude_s66b_screen.status';", "        st = Path(tmp) / 'claude_s68dev_screen.status';")
sub("rv = rdir / 's66b.json'", "rv = rdir / 's68dev.json'")
sub("        trusted = dict(lane='s66b', launcher_sha256=sha,", "        trusted = dict(lane='s68dev', launcher_sha256=sha,")
sub("check('T1 the lane read through analyze_lane (bound: canonical paths equal to TRUSTED, the reservation naming the lane / launcher sha / status / root, the armed line naming the sha and tree): the one arm, the same synthetic result,",
    "check('T1 the lane read through analyze_lane (bound: canonical paths equal to TRUSTED, the reservation naming the lane / launcher sha / status / root, the armed line naming the sha and tree): both arms, the same synthetic result,")
# the bar cases at +0.030
sub('''# s66b: at N = 3920 the fixture cannot place the mean exactly at +0.015 (2 x 0.015 x 3920 = 117.6 deals)''',
    '''# s68dev (bar +0.030): at N = 3920 the fixture cannot place the mean exactly at +0.030 (2 x 0.030 x 3920 = 235.2 deals); s66b's note on its +0.015 bar:
# s66b: at N = 3920 the fixture cannot place the mean exactly at +0.015 (2 x 0.015 x 3920 = 117.6 deals)''')
sub("o = run(rows(effect=0.015)); check('T2 +0.015 with noise at N 3920 (mean 0.01505): the verdict follows the CI condition exactly', o['bar']['verdict'] == ('DEV_PASS' if o['levels'][1] > 0 and o['levels'][0] >= 0.015 else 'DEV_FAIL') and abs(o['levels'][0] - 0.015) < 1 / (2 * DEALS), o['levels'])",
    "o = run(rows(effect=0.030)); check('T2 +0.030 with noise at N 3920 (mean 0.02997): the verdict follows the CI condition exactly', o['bar']['verdict'] == ('DEV_PASS' if o['levels'][1] > 0 and o['levels'][0] >= 0.030 else 'DEV_FAIL') and abs(o['levels'][0] - 0.030) < 1 / (2 * DEALS), o['levels'])")
sub("[0.015, 0.0001, 0.0299] if len(x) == DEALS else _boot(x, reps, seed)\no = run(rows(effect=0.015, noise=False)); check('T2 the mean exactly at +0.015 with CI lower > 0 -> DEV_PASS (the bar is inclusive; stubbed bootstrap on the deal series)', o['bar']['verdict'] == 'DEV_PASS' and o['levels'] == [0.015, 0.0001, 0.0299], o['levels'])",
    "[0.030, 0.0001, 0.0599] if len(x) == DEALS else _boot(x, reps, seed)\no = run(rows(effect=0.030, noise=False)); check('T2 the mean exactly at +0.030 with CI lower > 0 -> DEV_PASS (the bar is inclusive; stubbed bootstrap on the deal series)', o['bar']['verdict'] == 'DEV_PASS' and o['levels'] == [0.030, 0.0001, 0.0599], o['levels'])")
sub("[0.0149999, 0.0001, 0.0299] if len(x) == DEALS else _boot(x, reps, seed)\no = run(rows(effect=0.015, noise=False)); check('T2 the mean a hair below +0.015 with CI lower > 0 -> DEV_FAIL', o['bar']['verdict'] == 'DEV_FAIL' and o['levels'][0] == 0.0149999, o['levels'])",
    "[0.0299999, 0.0001, 0.0599] if len(x) == DEALS else _boot(x, reps, seed)\no = run(rows(effect=0.030, noise=False)); check('T2 the mean a hair below +0.030 with CI lower > 0 -> DEV_FAIL', o['bar']['verdict'] == 'DEV_FAIL' and o['levels'][0] == 0.0299999, o['levels'])")
sub("[0.02, 0.0, 0.04] if len(x) == DEALS else _boot(x, reps, seed)\no = run(rows(effect=0.015, noise=False)); check('T2 CI lower exactly 0 -> DEV_FAIL (lower must be > 0)'",
    "[0.04, 0.0, 0.08] if len(x) == DEALS else _boot(x, reps, seed)\no = run(rows(effect=0.030, noise=False)); check('T2 CI lower exactly 0 -> DEV_FAIL (lower must be > 0)'")
sub("o = run(rows(effect=0.010, noise=False)); check('T2 +0.010 noise-free (CI lower > 0, mean below +0.015) -> DEV_FAIL'",
    "o = run(rows(effect=0.025, noise=False)); check('T2 +0.025 noise-free (CI lower > 0, mean below +0.030) -> DEV_FAIL'")
sub('''check(f"T2 one {who} search record at 128 play worlds (both sides are configured at 64) -> DEV_INVALID"''', '''check(f"T2 one {who} search record at 128 play worlds (configured {PW[side]}) -> DEV_INVALID"''')
# T3 arm names
sub("'status: need, for arm sc8'", "f'status: need, for arm {ARM}'", count=4)
sub("status=status_text(drop_end='sc8'))", "status=status_text(drop_end=ARM))")
sub("status=status_text(start=START.replace('=sc8', '=sc9')))", "status=status_text(start=START.replace('S66_EXPLOITER=sc8', 'S66_EXPLOITER=sc9')))")
sub('''refused('T3 a SHA256SUMS whose ./sc8/duel.jsonl line differs refused', 'SHA256SUMS', rs, sums=lambda h: f'{"0" * 64}  ./sc8/duel.jsonl\\n{h}  ./fly.toml\\n')''',
    '''refused('T3 a SHA256SUMS whose ./<arm>/duel.jsonl line differs refused', 'SHA256SUMS', rs, sums=lambda h: f'{"0" * 64}  ./{ARM}/duel.jsonl\\n{h}  ./fly.toml\\n')''')
sub('''o = run(rs, sums=lambda h: f'{"1" * 64}  ./fly.toml\\n{h}  ./sc8/duel.jsonl\\n');''', '''o = run(rs, sums=lambda h: f'{"1" * 64}  ./fly.toml\\n{h}  ./{ARM}/duel.jsonl\\n');''')
sub("rd.ARM_SPEC['sc8']['cand']", "rd.ARM_SPEC[ARM]['cand']", count=2)
# T4: both arms in the bound layout
sub('''with tempfile.TemporaryDirectory(prefix='s66b-bind-', dir='/private/tmp') as tmp:
    for arm in rd.ARM_ORDER:
        (Path(tmp) / arm).mkdir(); p = write(base, tmp, name=f'{arm}/duel.jsonl')
    (Path(tmp) / 'SHA256SUMS').write_text(f'{hashlib.sha256(Path(p).read_bytes()).hexdigest()}  ./sc8/duel.jsonl\\n')''',
    '''with tempfile.TemporaryDirectory(prefix='s68dev-bind-', dir='/private/tmp') as tmp:
    sums = []
    for arm in rd.ARM_ORDER:
        (Path(tmp) / arm).mkdir(); pa = write(arm_rows(base, arm), tmp, name=f'{arm}/duel.jsonl')
        sums.append(f'{hashlib.sha256(Path(pa).read_bytes()).hexdigest()}  ./{arm}/duel.jsonl')
        if arm == ARM:
            p = pa
    (Path(tmp) / 'SHA256SUMS').write_text('\\n'.join(sums) + '\\n')''')
sub("lane['sc8']['bar']['verdict'] == 'DEV_PASS' and opened and opened[0].endswith('claude_s66b_screen.status')",
    "all(lane[a_]['bar']['verdict'] == 'DEV_PASS' for a_ in rd.ARM_ORDER) and opened and opened[0].endswith('claude_s68dev_screen.status')")
sub("other = Path(tmp) / 'other_root'; other.mkdir(); (other / 'sc8').mkdir(); (other / 'sc8' / 'duel.jsonl').write_bytes(Path(p).read_bytes());",
    "other = Path(tmp) / 'other_root'; other.mkdir()\n    for arm in rd.ARM_ORDER:\n        (other / arm).mkdir(); (other / arm / 'duel.jsonl').write_bytes((Path(root_) / arm / 'duel.jsonl').read_bytes())\n   ")
sub("    j['lane'] = 's66b'; Path(rv_).write_text(json.dumps(j) + '\\n')", "    j['lane'] = 's68dev'; Path(rv_).write_text(json.dumps(j) + '\\n')")
sub("rd.analyze(str(Path(root_) / 'sc8' / 'duel.jsonl'), arm='sc8',", "rd.analyze(str(Path(root_) / ARM / 'duel.jsonl'), arm=ARM,", count=2)
code = "\n".join(l for l in s.split("\n") if not l.lstrip().startswith("#"))
for tok in ("'s66b'", "s66b_read'", "claude_s66b", "arm='sc8'", "ARM_SPEC['sc8']", "./sc8/"):
    assert tok not in code, tok
compile(s, "test_s68dev_read.py", "exec")
(H / "test_s68dev_read.py").open("x").write(s)
print("test_s68dev_read.py sha256", sha(s.encode()), f"({n} asserted edits from s66b's 53e1efec)")
